method compare(game: array<int>, guess: array<int>) returns (result: array<int>)
    requires game.Length == guess.Length
    requires game.Length > 0
    ensures result.Length == game.Length
    ensures forall i :: 0 <= i < game.Length ==> result[i] == abs(game[i] - guess[i])
{
    var n := game.Length;
    result := new int[n];

    var i := 0;
    while i < n
        invariant 0 <= i <= n
        invariant forall j :: 0 <= j < i ==> result[j] == abs(game[j] - guess[j])
    {
        result[i] := abs(game[i] - guess[i]);
        i := i + 1;
    }
}
